    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <meta name="csrf-token" content="{{ csrf_token() }}">
        <title>Smart Glove SIBI</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <script src="https://unpkg.com/lucide@latest"></script>
        <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
        <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
        <script src="https://unpkg.com/mqtt/dist/mqtt.min.js"></script>
        <style>
            @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');
            body { font-family: 'Inter', sans-serif; background-color: #020617; background-image: radial-gradient(circle at 50% 0%, #1e293b 0%, #020617 70%); background-attachment: fixed; }
            ::-webkit-scrollbar { width: 4px; } ::-webkit-scrollbar-track { background: transparent; } ::-webkit-scrollbar-thumb { background: #334155; border-radius: 2px; }
            input[type="number"]::-webkit-inner-spin-button, input[type="number"]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
            .data-bar { transition: width 0.04s linear; }
            .glass-card { background: rgba(30, 41, 59, 0.4); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border: 1px solid rgba(255, 255, 255, 0.05); box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1); }
            .glass-input { background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 255, 255, 0.1); color: #f8fafc; transition: all 0.2s; }
            .glass-input:focus { border-color: #3b82f6; outline: none; }
        </style>
    </head>
    <body class="min-h-screen text-slate-50 antialiased relative">
        <div class="max-w-7xl mx-auto px-4 py-6">
            <x-header />
            <x-stream-stats />
            <x-sensor-data />
        </div>
        <x-calibration-modal />
        <x-vocabulary-modal />
        <x-evaluation-modal />
        <x-latency-modal />
        <div id="toast-container" class="fixed bottom-6 right-6 z-[60] flex flex-col gap-3"></div>

        <script>
            lucide.createIcons();
            let mqttClient = null, isConnected = false, manualDisconnect = false, packetsPerSecond = 0, vocabDictionary = [], gestureHistoryBuffer = [], activeGesture = null, releaseFramesCount = 0;
            let isCalibrationModalShown = false, isVocabModalShown = false, isEvalModalShown = false;
            let emaFlex = [0, 0, 0, 0, 0], smoothedAx = 0, smoothedAy = 0, smoothedAz = 0;
            let appCalibration = { f: [0,0,0,0,0], b: [4095,4095,4095,4095,4095], ax: 0, ay: 0, az: 0, gx: 0, gy: 0, gz: 0 };
            let evalData = [], isEvaluating = false, evalStartTime = 0, currentSample = 0, evalTotalRuntime = 0, evalTarget = null;
            const EMA_ALPHA_IMU = 0.08, STABLE_FRAMES_REQUIRED = 10, RELEASE_FRAMES_REQUIRED = 15;
            const uiElements = {}, e = (id) => document.getElementById(id);
            ['pps', 'pk', 'tr-out', 'hist', 'b-cn', 's-dot', 'd-st', 'ax', 'ay', 'az', 'gx', 'gy', 'gz', 'f1', 'f2', 'f3', 'f4', 'f5', 'fw1', 'fw2', 'fw3', 'fw4', 'fw5', 'current-sign', 'm-acc', 'm-tot', 'm-err', 'm-time', 'matrix-container', 'metrics-container'].forEach(id => uiElements[id] = e(id));
            
            setInterval(() => { if (uiElements.pps) uiElements.pps.innerText = packetsPerSecond + ' Hz'; packetsPerSecond = 0; }, 1000);
            
            const showToast = (msg, type = 'success') => { let d = document.createElement('div'); d.className = `px-4 py-3 rounded-lg shadow-xl text-sm font-medium text-white flex items-center gap-2 transform transition-all duration-300 translate-y-0 opacity-100 ${type === 'success' ? 'bg-emerald-600' : 'bg-red-600'}`; d.innerHTML = type === 'success' ? `<i data-lucide="check-circle" class="w-4 h-4"></i> ${msg}` : `<i data-lucide="alert-circle" class="w-4 h-4"></i> ${msg}`; e('toast-container').appendChild(d); lucide.createIcons(); setTimeout(() => { d.style.opacity = '0'; d.style.transform = 'translateY(10px)'; setTimeout(() => d.remove(), 300); }, 3000); };
            
            const initializeTTS = () => { if (window.speechSynthesis) window.speechSynthesis.cancel(); };
            const playTTS = (text, targetLang) => { if (!window.speechSynthesis || !text) return; window.speechSynthesis.cancel(); let spokenText = text.length === 1 ? text.toLowerCase() : text; let utterance = new SpeechSynthesisUtterance(spokenText); let langCode = targetLang === 'en' ? 'en-US' : (targetLang === 'ja' ? 'ja-JP' : 'id-ID'); utterance.lang = langCode; let voices = window.speechSynthesis.getVoices(); let selectedGender = e('v-gender') ? e('v-gender').value : 'female'; let prefix = langCode.split('-')[0].toLowerCase(); let langVoices = voices.filter(x => x.lang.replace('_', '-').toLowerCase().startsWith(prefix)); if (langVoices.length > 0) { let isMale = selectedGender === 'male'; let kw = isMale ? ['male', 'boy', 'david', 'mark', 'brian', 'james', 'ichiro', 'keita', 'andika'] : ['female', 'girl', 'zira', 'susan', 'lisa', 'gadis', 'damayanti', 'kyoko', 'haruka', 'victoria']; let voice = langVoices.find(x => kw.some(k => x.name.toLowerCase().includes(k))) || langVoices.find(x => x.name.toLowerCase().includes('google')) || (isMale && langVoices.length > 1 ? langVoices[1] : langVoices[0]); utterance.voice = voice; } window.speechSynthesis.speak(utterance); if (window.speechSynthesis.paused) window.speechSynthesis.resume(); };
            window.speechSynthesis.onvoiceschanged = () => window.speechSynthesis.getVoices();
            
            let dataChart = new Chart(e('chrt').getContext('2d'), { type: 'line', data: { labels: [], datasets: [ { label: 'Thumb', borderColor: '#3b82f6', data: [], borderWidth: 1.5, tension: 0.1 }, { label: 'Index', borderColor: '#10b981', data: [], borderWidth: 1.5, tension: 0.1 }, { label: 'Middle', borderColor: '#f59e0b', data: [], borderWidth: 1.5, tension: 0.1 }, { label: 'Ring', borderColor: '#8b5cf6', data: [], borderWidth: 1.5, tension: 0.1 }, { label: 'Pinky', borderColor: '#ec4899', data: [], borderWidth: 1.5, tension: 0.1 } ] }, options: { responsive: true, maintainAspectRatio: false, animation: false, elements: { point: { radius: 0 } }, scales: { x: { display: false }, y: { grid: { color: '#1e293b' }, min: 0, max: 100 } } } });
            const updateChart = (data) => { dataChart.data.labels.push(''); if (dataChart.data.labels.length > 40) { dataChart.data.labels.shift(); dataChart.data.datasets.forEach(s => s.data.shift()); } for (let i = 1; i <= 5; i++) dataChart.data.datasets[i - 1].data.push(data[`F${i}`]); dataChart.update(); };
            
            let scene3D = new THREE.Scene(), camera3D = new THREE.PerspectiveCamera(50, 1, 0.1, 1000), renderer3D = new THREE.WebGLRenderer({ alpha: true, antialias: true }); renderer3D.setSize(150, 150); if (e('th-c')) e('th-c').appendChild(renderer3D.domElement);
            let ambientLight = new THREE.AmbientLight(0xffffff, 0.6), dirLight = new THREE.DirectionalLight(0xffffff, 0.8); dirLight.position.set(5, 10, 7); scene3D.add(ambientLight, dirLight);
            let handGroup = new THREE.Group(), handMaterial = new THREE.MeshStandardMaterial({ color: 0x3b82f6, roughness: 0.4, metalness: 0.2 }); scene3D.add(handGroup); camera3D.position.z = 8;
            let palmMesh = new THREE.Mesh(new THREE.BoxGeometry(2.2, 2.5, 0.5), handMaterial); handGroup.add(palmMesh);
            let fingers3D = [];
            const createFinger = (w, l, d, x, y, z, rz) => { let group = new THREE.Group(), joint2 = new THREE.Group(), joint3 = new THREE.Group(), p1 = new THREE.Mesh(new THREE.BoxGeometry(w, l, d), handMaterial), p2 = new THREE.Mesh(new THREE.BoxGeometry(w, l * 0.8, d), handMaterial), p3 = new THREE.Mesh(new THREE.BoxGeometry(w, l * 0.6, d), handMaterial); group.position.set(x, y, z); group.rotation.z = rz; p1.position.y = l / 2; group.add(p1); joint2.position.y = l; group.add(joint2); p2.position.y = l * 0.4; joint2.add(p2); joint3.position.y = l * 0.8; joint2.add(joint3); p3.position.y = l * 0.3; joint3.add(p3); handGroup.add(group); return { root: group, joint2: joint2, joint3: joint3 }; };
            fingers3D.push(createFinger(0.5, 1.2, 0.5, -1.2, -0.5, 0, 0.5)); fingers3D.push(createFinger(0.4, 1.4, 0.4, -0.8, 1.25, 0, 0)); fingers3D.push(createFinger(0.4, 1.6, 0.4, -0.25, 1.25, 0, 0)); fingers3D.push(createFinger(0.4, 1.4, 0.4, 0.3, 1.25, 0, 0)); fingers3D.push(createFinger(0.3, 1.1, 0.3, 0.85, 1.25, 0, 0));
            const animate3D = () => { requestAnimationFrame(animate3D); renderer3D.render(scene3D, camera3D); }; animate3D();
            const update3DHand = (ax, ay, az, f1, f2, f3, f4, f5) => { handGroup.rotation.set(ay, ax, az); let flexValues = [f1, f2, f3, f4, f5]; for (let i = 0; i < 5; i++) { let bendAngle = (flexValues[i] / 100) * 1.4; fingers3D[i].root.rotation.x = bendAngle; fingers3D[i].joint2.rotation.x = bendAngle; fingers3D[i].joint3.rotation.x = bendAngle; } };
            
            const processGesture = async (gestureName) => { if (!gestureName) return; if (uiElements['current-sign']) uiElements['current-sign'].innerText = gestureName; let targetLang = e('t-lang').value; if (targetLang === 'id') { if (uiElements['tr-out']) uiElements['tr-out'].innerText = gestureName; playTTS(gestureName, 'id'); if (uiElements.hist) { uiElements.hist.insertAdjacentHTML('afterbegin', `<div class="flex justify-between items-center bg-slate-800/50 p-2 rounded mb-1"><span class="text-xs text-white">${gestureName}</span><button onclick="playTTS('${gestureName}','id')" class="text-blue-400"><i data-lucide="play" class="w-3 h-3"></i></button></div>`); lucide.createIcons(); } } else { try { let res = await fetch('/api/translate', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content }, body: JSON.stringify({ text: gestureName, target: targetLang }) }); if (!res.ok) throw new Error(); let data = await res.json(), translatedText = data.translated; if (uiElements['tr-out']) uiElements['tr-out'].innerText = translatedText; playTTS(translatedText, targetLang); if (uiElements.hist) { uiElements.hist.insertAdjacentHTML('afterbegin', `<div class="flex justify-between items-center bg-slate-800/50 p-2 rounded mb-1"><span class="text-xs text-white">${gestureName} <span class="text-slate-500">(${translatedText})</span></span><button onclick="playTTS('${translatedText}','${targetLang}')" class="text-blue-400"><i data-lucide="play" class="w-3 h-3"></i></button></div>`); lucide.createIcons(); } } catch (err) { if (uiElements['tr-out']) uiElements['tr-out'].innerText = gestureName + " (Offline)"; playTTS(gestureName, 'id'); } } };
            const clearHistory = () => { if (uiElements['tr-out']) uiElements['tr-out'].innerText = ''; if (uiElements['current-sign']) uiElements['current-sign'].innerText = ''; if (uiElements.hist) uiElements.hist.innerHTML = ''; activeGesture = null; gestureHistoryBuffer = []; };
            const matchGesture = (flexArray, imuData) => { let roundedFlex = flexArray.map(Math.round); let match = vocabDictionary.find(v => roundedFlex[0] >= parseInt(v.f1_min) && roundedFlex[0] <= parseInt(v.f1_max) && roundedFlex[1] >= parseInt(v.f2_min) && roundedFlex[1] <= parseInt(v.f2_max) && roundedFlex[2] >= parseInt(v.f3_min) && roundedFlex[2] <= parseInt(v.f3_max) && roundedFlex[3] >= parseInt(v.f4_min) && roundedFlex[3] <= parseInt(v.f4_max) && roundedFlex[4] >= parseInt(v.f5_min) && roundedFlex[4] <= parseInt(v.f5_max) && imuData.ax >= parseFloat(v.ax_min) && imuData.ax <= parseFloat(v.ax_max) && imuData.ay >= parseFloat(v.ay_min) && imuData.ay <= parseFloat(v.ay_max) && imuData.az >= parseFloat(v.az_min) && imuData.az <= parseFloat(v.az_max)); return match ? match.meaning_id : null; };
            
            async function fetchPresets() { try { let res = await fetch('/api/calibrations'), data = await res.json(), select = e('p-select'); select.innerHTML = '<option value="">Select Preset...</option>'; data.forEach(p => select.insertAdjacentHTML('beforeend', `<option value="${p.name}">${p.name}</option>`)); } catch (err) {} }
            async function fetchVocabularies() { try { let r = await fetch('/api/vocabularies'); vocabDictionary = await r.json(); let select = e('v-select'); if (select) { let currentVal = select.value; select.innerHTML = '<option value="">Select Gesture...</option>'; vocabDictionary.forEach(v => select.insertAdjacentHTML('beforeend', `<option value="${v.id}">${v.name} (${v.meaning_id})</option>`)); select.value = currentVal; } } catch (err) {} }
            document.addEventListener('DOMContentLoaded', () => { fetchPresets(); fetchVocabularies(); });
            
            function updateActiveCalibration() { for (let i = 0; i < 5; i++) { appCalibration.f[i] = parseInt(e(`cf${i}`)?.value) || 0; appCalibration.b[i] = parseInt(e(`cb${i}`)?.value) || 4095; } ['ax', 'ay', 'az', 'gx', 'gy', 'gz'].forEach(k => appCalibration[k] = parseFloat(e(`${k}_d`)?.value) || 0); }
            async function loadPreset() { let profileName = e('p-select').value; if (!profileName) return showToast('Please select a preset', 'error'); try { let response = await fetch('/api/calibrations/' + profileName); if (!response.ok) throw new Error(); let data = await response.json(); for (let i = 0; i < 5; i++) { if(e(`cf${i}`)) e(`cf${i}`).value = data[`f${i}`]; if(e(`cb${i}`)) e(`cb${i}`).value = data[`b${i}`]; } ['ax', 'ay', 'az', 'gx', 'gy', 'gz'].forEach(k => { if(e(`${k}_d`)) e(`${k}_d`).value = data[k]; }); updateActiveCalibration(); e('p-nm').value = profileName; showToast('Preset applied successfully'); } catch (err) { showToast('Failed to load preset', 'error'); } }
            async function saveProfile() { let profileName = e('p-nm').value; if(!profileName) return showToast('Enter a profile name', 'error'); let profileData = { name: profileName, _token: document.querySelector('meta[name="csrf-token"]').content, ax: e('ax_d').value, ay: e('ay_d').value, az: e('az_d').value, gx: e('gx_d').value, gy: e('gy_d').value, gz: e('gz_d').value }; for (let i = 0; i < 5; i++) { profileData[`f${i}`] = e(`cf${i}`).value; profileData[`b${i}`] = e(`cb${i}`).value; } try { let response = await fetch('/api/calibrations', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(profileData) }); if (response.ok) { showToast('Profile saved successfully'); fetchPresets(); } else throw new Error(); } catch (err) { showToast('Failed to save profile', 'error'); } }
            
            function toggleCalibrationModal() { isCalibrationModalShown = !isCalibrationModalShown; if (e('c-md')) e('c-md').style.display = isCalibrationModalShown ? 'flex' : 'none'; }
            function toggleVocabularyModal() { isVocabModalShown = !isVocabModalShown; if (e('v-md')) { e('v-md').style.display = isVocabModalShown ? 'flex' : 'none'; if(isVocabModalShown) { fetchVocabularies().then(renderVocabTable); closeVocabEditor(); } } }
            function renderVocabTable() { let q = e('v-search').value.toLowerCase(); let filtered = vocabDictionary.filter(v => v.name.toLowerCase().includes(q) || v.meaning_id.toLowerCase().includes(q)).sort((a, b) => a.name.localeCompare(b.name)); let html = ''; filtered.forEach(v => { html += `<tr class="hover:bg-slate-800/50 transition-colors"><td class="p-3 text-white font-medium">${v.name}</td><td class="p-3 text-slate-300">${v.meaning_id}</td><td class="p-3 text-slate-400">${v.meaning_en || '-'}</td><td class="p-3"><div class="flex gap-2 justify-end"><button onclick="openVocabEditor(${v.id})" class="text-blue-400 hover:text-blue-300 p-1.5 bg-blue-500/10 rounded transition-colors"><i data-lucide="edit-2" class="w-4 h-4"></i></button><button onclick="deleteVocab(${v.id})" class="text-red-400 hover:text-red-300 p-1.5 bg-red-500/10 rounded transition-colors"><i data-lucide="trash-2" class="w-4 h-4"></i></button></div></td></tr>`; }); e('v-tbody').innerHTML = html || '<tr><td colspan="4" class="p-6 text-center text-slate-500 italic">No gestures found.</td></tr>'; lucide.createIcons(); }
            function openVocabEditor(id = null) { e('v-list-view').style.display = 'none'; e('v-editor-view').style.display = 'block'; if (id) { let v = vocabDictionary.find(x => x.id === id); e('v_edit_id').value = v.id; e('v_name').value = v.name; e('v_mean_id').value = v.meaning_id; e('v_mean_en').value = v.meaning_en || ''; e('v_mean_ja').value = v.meaning_ja || ''; for(let i=1; i<=5; i++) { e(`v_f${i}_min`).value = v[`f${i}_min`]; e(`v_f${i}_max`).value = v[`f${i}_max`]; } ['x', 'y', 'z'].forEach(axis => { e(`v_a${axis}_min`).value = v[`a${axis}_min`]; e(`v_a${axis}_max`).value = v[`a${axis}_max`]; }); } else { e('v_edit_id').value = ''; e('v_name').value = ''; e('v_mean_id').value = ''; e('v_mean_en').value = ''; e('v_mean_ja').value = ''; for(let i=1; i<=5; i++) { e(`v_f${i}_min`).value = 0; e(`v_f${i}_max`).value = 100; } ['x', 'y', 'z'].forEach(axis => { e(`v_a${axis}_min`).value = -1.0; e(`v_a${axis}_max`).value = 1.0; }); } }
            function closeVocabEditor() { e('v-list-view').style.display = 'block'; e('v-editor-view').style.display = 'none'; }
            async function saveVocabChanges() { let payload = { _token: document.querySelector('meta[name="csrf-token"]').content, id: e('v_edit_id').value, name: e('v_name').value, meaning_id: e('v_mean_id').value, meaning_en: e('v_mean_en').value, meaning_ja: e('v_mean_ja').value }; if(!payload.name || !payload.meaning_id) return showToast('System Name and Indonesian meaning are required', 'error'); for(let i=1; i<=5; i++) { payload[`f${i}_min`] = parseInt(e(`v_f${i}_min`).value) || 0; payload[`f${i}_max`] = parseInt(e(`v_f${i}_max`).value) || 100; } ['x', 'y', 'z'].forEach(axis => { payload[`a${axis}_min`] = parseFloat(e(`v_a${axis}_min`).value) || 0; payload[`a${axis}_max`] = parseFloat(e(`v_a${axis}_max`).value) || 0; }); try { let res = await fetch('/api/vocabularies/save', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, body: JSON.stringify(payload) }); if (res.ok) { showToast('Vocabulary saved successfully'); await fetchVocabularies(); renderVocabTable(); closeVocabEditor(); } else throw new Error(); } catch (err) { showToast('Failed to save vocabulary', 'error'); } }
            async function deleteVocab(id) { if(!confirm('Delete this gesture?')) return; try { let res = await fetch(`/api/vocabularies/${id}`, { method: 'DELETE', headers: { 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content } }); if (res.ok) { showToast('Gesture deleted'); await fetchVocabularies(); renderVocabTable(); } else throw new Error(); } catch (err) { showToast('Failed to delete gesture', 'error'); } }
            
            function toggleEvaluationModal() { isEvalModalShown = !isEvalModalShown; if (e('e-md')) { e('e-md').style.display = isEvalModalShown ? 'flex' : 'none'; if (isEvalModalShown) { let select = e('e-target'); select.innerHTML = '<option value="">Select Target...</option>'; vocabDictionary.forEach(v => select.insertAdjacentHTML('beforeend', `<option value="${v.meaning_id}">${v.name} (${v.meaning_id})</option>`)); renderConfusionMatrix(); } } }
            
            function startEvaluation() { evalTarget = e('e-target').value; let maxSamples = parseInt(e('e-samples').value); if (!evalTarget || isNaN(maxSamples) || !isConnected) return showToast('Check inputs and connection', 'error'); isEvaluating = true; currentSample = 0; evalStartTime = Date.now(); e('btn-start-eval').disabled = true; e('e-status').classList.remove('hidden'); e('e-total').innerText = maxSamples; e('e-counter').innerText = '0'; showToast('Evaluation started. Perform gestures now.'); }

            function handleEvaluationEvent(predicted, frameData) { if (!isEvaluating) return; let predLabel = (!predicted || predicted.trim() === "") ? "0" : predicted; let isCorrect = (predLabel === evalTarget); let maxSamples = parseInt(e('e-samples').value); currentSample++; e('e-counter').innerText = currentSample; let logEntry = { timestamp: new Date().toISOString(), actual: evalTarget, predicted: predLabel, isCorrect: isCorrect, raw: frameData.raw, flex: frameData.flex, imu: frameData.imu }; evalData.push(logEntry); renderConfusionMatrix(); if (currentSample >= maxSamples) { isEvaluating = false; evalTotalRuntime += (Date.now() - evalStartTime) / 1000; e('btn-start-eval').disabled = false; e('e-status').classList.add('hidden'); if(e('m-time')) e('m-time').innerText = evalTotalRuntime.toFixed(1); showToast('Evaluation complete'); } }

            function clearEvaluation() { evalData = []; evalTotalRuntime = 0; if(e('m-time')) e('m-time').innerText = '0.0'; renderConfusionMatrix(); }
            
            function renderConfusionMatrix() { if(e('m-tot')) e('m-tot').innerText = evalData.length; if (evalData.length === 0) { if(e('matrix-container')) e('matrix-container').innerHTML = '<div class="flex h-full items-center justify-center text-slate-500 italic py-10">No evaluation data available.</div>'; if(e('metrics-container')) e('metrics-container').innerHTML = '<div class="flex h-full items-center justify-center text-slate-500 italic py-10">Awaiting data...</div>'; if(e('m-acc')) e('m-acc').innerText = '0.00%'; if(e('m-err')) e('m-err').innerText = '0'; return; } let classes = [...new Set([...evalData.map(d => d.actual), ...evalData.map(d => d.predicted)])].sort((a, b) => { if (a === '0') return 1; if (b === '0') return -1; return a.localeCompare(b); }); let matrix = {}; classes.forEach(c => { matrix[c] = {}; classes.forEach(p => matrix[c][p] = 0); }); let correct = 0; evalData.forEach(d => { matrix[d.actual][d.predicted]++; if (d.actual === d.predicted) correct++; }); if(e('m-acc')) e('m-acc').innerText = (correct / evalData.length * 100).toFixed(2) + '%'; if(e('m-err')) e('m-err').innerText = evalData.length - correct; let maxVal = Math.max(...classes.flatMap(c => Object.values(matrix[c]))); let mHtml = '<table class="w-full text-center border-collapse whitespace-nowrap"><thead class="bg-slate-900/50 sticky top-0 z-10"><tr><th class="p-2 border border-slate-700 text-left text-slate-400 font-medium">Act \\ Pred</th>'; classes.forEach(c => mHtml += `<th class="p-2 border border-slate-700 font-medium text-slate-300 w-12">${c}</th>`); mHtml += '</tr></thead><tbody>'; classes.forEach(actual => { let rowSum = Object.values(matrix[actual]).reduce((a, b) => a + b, 0); if(rowSum > 0) { mHtml += `<tr><th class="p-2 border border-slate-700 bg-slate-900/50 text-left font-medium text-slate-300 sticky left-0 z-10">${actual}</th>`; classes.forEach(predicted => { let val = matrix[actual][predicted], alpha = val > 0 ? Math.max(0.2, val / maxVal) : 0, bgStyle = val > 0 ? (actual === predicted ? `background-color: rgba(16, 185, 129, ${alpha})` : `background-color: rgba(239, 68, 68, ${alpha})`) : ''; mHtml += `<td class="p-2 border border-slate-700 ${val === 0 ? 'text-slate-600' : (actual === predicted ? 'text-emerald-100 font-bold' : 'text-red-100 font-bold')}" style="${bgStyle}">${val}</td>`; }); mHtml += '</tr>'; } }); mHtml += '</tbody></table>'; if(e('matrix-container')) e('matrix-container').innerHTML = mHtml; let sHtml = '<table class="w-full text-center border-collapse whitespace-nowrap"><thead class="bg-slate-900/50 sticky top-0"><tr><th class="p-2 border border-slate-700 text-left text-slate-400 font-medium">Class</th><th class="p-2 border border-slate-700 font-medium text-slate-300">Precision</th><th class="p-2 border border-slate-700 font-medium text-slate-300">Recall</th><th class="p-2 border border-slate-700 font-medium text-slate-300">F1-Score</th><th class="p-2 border border-slate-700 font-medium text-slate-300">Support</th></tr></thead><tbody>'; classes.forEach(c => { let tp = matrix[c][c] || 0, fp = classes.reduce((sum, i) => sum + matrix[i][c], 0) - tp, fn = classes.reduce((sum, j) => sum + matrix[c][j], 0) - tp, p = tp + fp > 0 ? tp / (tp + fp) : 0, r = tp + fn > 0 ? tp / (tp + fn) : 0, f1 = p + r > 0 ? 2 * (p * r) / (p + r) : 0, support = tp + fn; if(support > 0 || tp + fp > 0) { sHtml += `<tr class="hover:bg-slate-800/50 transition-colors"><th class="p-2 border border-slate-700 text-left font-medium text-slate-300">${c}</th><td class="p-2 border border-slate-700 text-slate-300">${(p * 100).toFixed(1)}%</td><td class="p-2 border border-slate-700 text-slate-300">${(r * 100).toFixed(1)}%</td><td class="p-2 border border-slate-700 text-slate-300">${(f1 * 100).toFixed(1)}%</td><td class="p-2 border border-slate-700 text-slate-400">${support}</td></tr>`; } }); sHtml += '</tbody></table>'; if(e('metrics-container')) e('metrics-container').innerHTML = sHtml; }

            function exportEvaluationCSV() { if (evalData.length === 0) return showToast('No data to export', 'error'); let csvContent = "data:text/csv;charset=utf-8,Timestamp,Actual,Predicted,R1,R2,R3,R4,R5,F1,F2,F3,F4,F5,Ax,Ay,Az,Gx,Gy,Gz\n"; evalData.forEach(d => { let row = [d.timestamp, d.actual, d.predicted, ...d.raw, ...d.flex.map(f => f.toFixed(2)), d.imu.ax.toFixed(3), d.imu.ay.toFixed(3), d.imu.az.toFixed(3), d.imu.gx.toFixed(3), d.imu.gy.toFixed(3), d.imu.gz.toFixed(3)]; csvContent += row.join(",") + "\n"; }); let encodedUri = encodeURI(csvContent), link = document.createElement("a"); link.setAttribute("href", encodedUri); link.setAttribute("download", `evaluation_log_${new Date().getTime()}.csv`); document.body.appendChild(link); link.click(); document.body.removeChild(link); }
            
            const updateConnectionButton = () => { if (!uiElements['b-cn']) return; uiElements['b-cn'].innerHTML = isConnected ? '<i data-lucide="wifi-off" class="w-4 h-4"></i> Disconnect' : '<i data-lucide="wifi" class="w-4 h-4"></i> Connect'; uiElements['b-cn'].className = isConnected ? 'bg-red-500/10 text-red-400 border border-red-500/20 px-4 py-2 rounded-lg flex items-center gap-2 text-sm' : 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-4 py-2 rounded-lg flex items-center gap-2 text-sm'; if (uiElements['s-dot']) uiElements['s-dot'].className = isConnected ? 'w-2 h-2 rounded-full bg-emerald-400 transition-colors duration-300' : 'w-2 h-2 rounded-full bg-slate-600 transition-colors duration-300'; if (e('st-t')) { e('st-t').innerText = isConnected ? 'System Online' : 'System Offline'; e('st-t').className = isConnected ? 'text-emerald-400 font-medium transition-colors duration-300' : 'text-slate-400 font-medium transition-colors duration-300'; } if (uiElements['d-st']) uiElements['d-st'].style.display = isConnected ? 'grid' : 'none'; lucide.createIcons(); };
            
            const toggleWebSocket = () => { if (!isConnected) { manualDisconnect = false; initializeTTS(); if (!mqttClient) { const clientId = 'sgsibi_' + Math.random().toString(16).substring(2, 10); mqttClient = mqtt.connect("wss://broker.hivemq.com:8884/mqtt", { clientId: clientId }); mqttClient.on("connect", () => { isConnected = true; updateConnectionButton(); showToast('Connected to MQTT Broker'); mqttClient.subscribe(["sg/sibi"]); }); mqttClient.on("message", (topic, message) => { try { let payload = JSON.parse(message.toString()); if (payload.ID !== undefined) { packetsPerSecond++; requestAnimationFrame(() => updateData(payload)); } } catch (x) {} }); mqttClient.on("close", () => { if (manualDisconnect) { isConnected = false; updateConnectionButton(); } }); mqttClient.on("offline", () => { if (manualDisconnect) { isConnected = false; updateConnectionButton(); } }); mqttClient.on("error", () => { if (manualDisconnect) { isConnected = false; updateConnectionButton(); } }); } else { mqttClient.reconnect(); } } else { manualDisconnect = true; if (mqttClient) { mqttClient.end(true); mqttClient = null; } isConnected = false; updateConnectionButton(); showToast('Disconnected from Broker', 'error'); } };
            
            const updateData = (data) => { let tRx = performance.now(); if (uiElements.pk) uiElements.pk.innerText = data.ID; let currentFlex = []; for (let i = 0; i < 5; i++) { let percent = 0; if (data[`R${i + 1}`] !== undefined) { let raw = parseFloat(data[`R${i + 1}`]); if (e(`raw_adc_${i}`)) e(`raw_adc_${i}`).innerText = Math.round(raw); let flat = appCalibration.f[i], bent = appCalibration.b[i]; if (flat < bent) { if (raw <= flat) percent = 0; else if (raw >= bent) percent = 100; else percent = ((raw - flat) * 100) / (bent - flat); } else { if (raw >= flat) percent = 0; else if (raw <= bent) percent = 100; else percent = ((flat - raw) * 100) / (flat - bent); } } else { percent = parseFloat(data[`F${i + 1}`]) || 0; } currentFlex.push(percent); if (uiElements[`f${i + 1}`]) uiElements[`f${i + 1}`].innerText = Math.round(percent) + '%'; if (uiElements[`fw${i + 1}`]) uiElements[`fw${i + 1}`].style.width = `${percent}%`; } let ax_raw = data.Ax !== undefined ? parseFloat(data.Ax) : 0; let ay_raw = data.Ay !== undefined ? parseFloat(data.Ay) : 0; let az_raw = data.Az !== undefined ? parseFloat(data.Az) : 0; let gx_raw = data.Gx !== undefined ? parseFloat(data.Gx) : 0; let gy_raw = data.Gy !== undefined ? parseFloat(data.Gy) : 0; let gz_raw = data.Gz !== undefined ? parseFloat(data.Gz) : 0; if (e('r_ax')) e('r_ax').innerText = ax_raw.toFixed(2); if (e('r_ay')) e('r_ay').innerText = ay_raw.toFixed(2); if (e('r_az')) e('r_az').innerText = az_raw.toFixed(2); if (e('r_gx')) e('r_gx').innerText = gx_raw.toFixed(2); if (e('r_gy')) e('r_gy').innerText = gy_raw.toFixed(2); if (e('r_gz')) e('r_gz').innerText = gz_raw.toFixed(2); let cx = ax_raw + appCalibration.ax, cy = ay_raw + appCalibration.ay, cz = az_raw + appCalibration.az; let gx = gx_raw + appCalibration.gx, gy = gy_raw + appCalibration.gy, gz = gz_raw + appCalibration.gz; smoothedAx = (EMA_ALPHA_IMU * cx) + ((1 - EMA_ALPHA_IMU) * smoothedAx); smoothedAy = (EMA_ALPHA_IMU * cy) + ((1 - EMA_ALPHA_IMU) * smoothedAy); smoothedAz = (EMA_ALPHA_IMU * cz) + ((1 - EMA_ALPHA_IMU) * smoothedAz); if (uiElements.ax) uiElements.ax.innerText = cx.toFixed(2); if (uiElements.ay) uiElements.ay.innerText = cy.toFixed(2); if (uiElements.az) uiElements.az.innerText = cz.toFixed(2); if (uiElements.gx) uiElements.gx.innerText = gx.toFixed(2); if (uiElements.gy) uiElements.gy.innerText = gy.toFixed(2); if (uiElements.gz) uiElements.gz.innerText = gz.toFixed(2); updateChart({ F1: currentFlex[0], F2: currentFlex[1], F3: currentFlex[2], F4: currentFlex[3], F5: currentFlex[4] }); update3DHand(smoothedAx, smoothedAy, smoothedAz, currentFlex[0], currentFlex[1], currentFlex[2], currentFlex[3], currentFlex[4]); let matchedGesture = matchGesture(currentFlex, {ax: smoothedAx, ay: smoothedAy, az: smoothedAz}); if (matchedGesture === null) { gestureHistoryBuffer = []; releaseFramesCount++; if (releaseFramesCount >= RELEASE_FRAMES_REQUIRED) activeGesture = null; } else { releaseFramesCount = 0; gestureHistoryBuffer.push(matchedGesture); if (gestureHistoryBuffer.length > STABLE_FRAMES_REQUIRED) gestureHistoryBuffer.shift(); if (gestureHistoryBuffer.length === STABLE_FRAMES_REQUIRED && gestureHistoryBuffer.every(x => x === matchedGesture)) { if (activeGesture !== matchedGesture) { let tComp = performance.now(); activeGesture = matchedGesture; processGesture(matchedGesture).then(() => { if (typeof recordLatency === 'function') recordLatency(data.ID, matchedGesture, tRx, tComp, performance.now()); }); if (isEvaluating) { handleEvaluationEvent(matchedGesture, { raw: [parseFloat(data.R1)||0, parseFloat(data.R2)||0, parseFloat(data.R3)||0, parseFloat(data.R4)||0, parseFloat(data.R5)||0], flex: currentFlex, imu: { ax: smoothedAx, ay: smoothedAy, az: smoothedAz, gx: gx, gy: gy, gz: gz } }); } } } } };
        </script>
    </body>
    </html>